CREATE TABLE public.operating_rules(singleton boolean PRIMARY KEY DEFAULT true CHECK(singleton), default_lease_weeks integer NOT NULL DEFAULT 4 CHECK(default_lease_weeks BETWEEN 1 AND 52), renewal_discount numeric NOT NULL DEFAULT 0.05 CHECK(renewal_discount BETWEEN 0 AND 1), avgas_kg_per_litre numeric NOT NULL DEFAULT 0.72 CHECK(avgas_kg_per_litre>0), jeta_kg_per_litre numeric NOT NULL DEFAULT 0.80 CHECK(jeta_kg_per_litre>0));
GRANT SELECT,UPDATE ON public.operating_rules TO authenticated; GRANT ALL ON public.operating_rules TO service_role;
ALTER TABLE public.operating_rules ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Players read operating rules" ON public.operating_rules FOR SELECT TO authenticated USING(true);
CREATE POLICY "Admin updates operating rules" ON public.operating_rules FOR UPDATE TO authenticated USING(public.is_admin()) WITH CHECK(public.is_admin());
INSERT INTO public.operating_rules(singleton) SELECT true FROM public.economy_config LIMIT 1;
ALTER TABLE public.fleet_aircraft ADD COLUMN returned_at timestamptz;
CREATE TABLE public.lease_contracts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), aircraft_id uuid NOT NULL REFERENCES public.fleet_aircraft(id), company_id uuid NOT NULL REFERENCES public.companies(id), starts_at timestamptz NOT NULL, ends_at timestamptz NOT NULL, term_weeks integer NOT NULL CHECK(term_weeks BETWEEN 1 AND 52), base_weekly_rate numeric NOT NULL CHECK(base_weekly_rate>=0), weekly_rate numeric NOT NULL CHECK(weekly_rate>=0), renewal boolean NOT NULL DEFAULT false, paid_weeks integer NOT NULL DEFAULT 1 CHECK(paid_weeks>=0), CHECK(ends_at>starts_at));
GRANT SELECT ON public.lease_contracts TO authenticated; GRANT ALL ON public.lease_contracts TO service_role;
ALTER TABLE public.lease_contracts ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Owner reads lease contracts" ON public.lease_contracts FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.companies c WHERE c.id=company_id AND c.user_id=auth.uid()));
CREATE INDEX lease_contracts_aircraft_idx ON public.lease_contracts(aircraft_id,starts_at DESC);
INSERT INTO public.lease_contracts(aircraft_id,company_id,starts_at,ends_at,term_weeks,base_weekly_rate,weekly_rate) SELECT id,company_id,leased_at,leased_at+interval '28 days',4,weekly_rate,weekly_rate FROM public.fleet_aircraft;
ALTER TABLE public.company_ledger DROP CONSTRAINT company_ledger_entry_type_check;
ALTER TABLE public.company_ledger ADD CONSTRAINT company_ledger_entry_type_check CHECK(entry_type IN ('INITIAL_GRANT','LEASE_DEPOSIT','LEASE_PAYMENT','LEASE_DEPOSIT_REFUND','TICKET_REVENUE','FUEL_EXPENSE','AIRPORT_FEES','HANDLING_FEES','MAINTENANCE_RESERVE'));
CREATE FUNCTION public.sync_lease_payments() RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE c companies%ROWTYPE; k lease_contracts%ROWTYPE; f fleet_aircraft%ROWTYPE; due integer; bal numeric; BEGIN SELECT * INTO c FROM companies WHERE user_id=auth.uid() FOR UPDATE; IF NOT FOUND THEN RETURN; END IF; bal:=company_balance(c.id); FOR k IN SELECT * FROM lease_contracts WHERE company_id=c.id ORDER BY starts_at,id FOR UPDATE LOOP SELECT * INTO f FROM fleet_aircraft WHERE id=k.aircraft_id; due:=least(k.term_weeks,greatest(1,floor(extract(epoch FROM now()-k.starts_at)/604800)::integer+1)); WHILE k.paid_weeks<due LOOP k.paid_weeks:=k.paid_weeks+1; bal:=bal-k.weekly_rate; INSERT INTO company_ledger(company_id,entry_type,debit_account,credit_account,amount,company_delta,balance_after,description,reference,idempotency_key) VALUES(c.id,'LEASE_PAYMENT','LESSOR_REVENUE','COMPANY_CASH',k.weekly_rate,-k.weekly_rate,bal,'Weekly lease payment – '||f.registration,f.registration,'contract:'||k.id||':week:'||k.paid_weeks); END LOOP; UPDATE lease_contracts SET paid_weeks=k.paid_weeks WHERE id=k.id; END LOOP; UPDATE fleet_aircraft f SET next_payment_due=(SELECT least(k.ends_at,k.starts_at+make_interval(days=>k.paid_weeks*7)) FROM lease_contracts k WHERE k.aircraft_id=f.id ORDER BY k.starts_at DESC LIMIT 1) WHERE f.company_id=c.id AND f.returned_at IS NULL; END $$;
CREATE FUNCTION public.sign_lease(p_type text,p_weeks integer DEFAULT 4) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE c companies%ROWTYPE; t aircraft_types%ROWTYPE; bal numeric; fid uuid:=gen_random_uuid(); reg text; BEGIN SELECT * INTO c FROM companies WHERE user_id=auth.uid() FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'No company'; END IF; PERFORM sync_lease_payments(); IF p_weeks NOT BETWEEN 1 AND 52 THEN RAISE EXCEPTION 'Lease term must be 1–52 weeks'; END IF; SELECT * INTO t FROM aircraft_types WHERE id=p_type AND active; IF NOT FOUND THEN RAISE EXCEPTION 'Unknown or inactive aircraft'; END IF; IF (SELECT count(*) FROM fleet_aircraft WHERE company_id=c.id AND returned_at IS NULL)>=economy_number('max_active_leases') THEN RAISE EXCEPTION 'Lease limit reached'; END IF; bal:=company_balance(c.id); IF bal<t.security_deposit+t.weekly_rate THEN RAISE EXCEPTION 'Insufficient Smooth Coins'; END IF; reg:='SS-'||c.icao_code||upper(substr(replace(fid::text,'-',''),1,6)); INSERT INTO fleet_aircraft(id,company_id,aircraft_type_id,registration,location_icao,lease_deposit,weekly_rate,next_payment_due) VALUES(fid,c.id,t.id,reg,c.home_base_icao,t.security_deposit,t.weekly_rate,now()+interval '7 days'); INSERT INTO lease_contracts(aircraft_id,company_id,starts_at,ends_at,term_weeks,base_weekly_rate,weekly_rate) VALUES(fid,c.id,now(),now()+make_interval(days=>7*p_weeks),p_weeks,t.weekly_rate,t.weekly_rate); INSERT INTO company_ledger(company_id,entry_type,debit_account,credit_account,amount,company_delta,balance_after,description,reference,idempotency_key) VALUES(c.id,'LEASE_DEPOSIT','LESSOR_DEPOSITS','COMPANY_CASH',t.security_deposit,-t.security_deposit,bal-t.security_deposit,'Security deposit – '||reg,reg,'lease_deposit:'||fid),(c.id,'LEASE_PAYMENT','LESSOR_REVENUE','COMPANY_CASH',t.weekly_rate,-t.weekly_rate,bal-t.security_deposit-t.weekly_rate,'First weekly lease payment – '||reg,reg,'lease_payment:'||fid||':1'); RETURN fid; END $$;
CREATE OR REPLACE FUNCTION public.lease_aircraft(p_type text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN RETURN public.sign_lease(p_type,(SELECT default_lease_weeks FROM operating_rules WHERE singleton)); END $$;
CREATE FUNCTION public.manage_lease(p_aircraft uuid,p_action text,p_weeks integer DEFAULT 4) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE c companies%ROWTYPE; f fleet_aircraft%ROWTYPE; k lease_contracts%ROWTYPE; bal numeric; rate numeric; base numeric; discount numeric; kid uuid; BEGIN SELECT * INTO c FROM companies WHERE user_id=auth.uid() FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'No company'; END IF; PERFORM sync_lease_payments(); SELECT * INTO f FROM fleet_aircraft WHERE id=p_aircraft AND company_id=c.id FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Aircraft not found'; END IF; IF f.returned_at IS NOT NULL THEN RETURN f.id; END IF; SELECT * INTO k FROM lease_contracts WHERE aircraft_id=f.id ORDER BY starts_at DESC LIMIT 1 FOR UPDATE; IF now()<k.ends_at THEN RAISE EXCEPTION 'Contract has not expired yet'; END IF; IF EXISTS(SELECT 1 FROM flights WHERE aircraft_id=f.id AND status IN ('DISPATCHED','EN_ROUTE')) THEN RAISE EXCEPTION 'Complete or cancel the active flight first'; END IF; bal:=company_balance(c.id); IF p_action='return' THEN INSERT INTO company_ledger(company_id,entry_type,debit_account,credit_account,amount,company_delta,balance_after,description,reference,idempotency_key) VALUES(c.id,'LEASE_DEPOSIT_REFUND','COMPANY_CASH','LESSOR_DEPOSITS',f.lease_deposit,f.lease_deposit,bal+f.lease_deposit,'Deposit refunded – '||f.registration,f.registration,'lease_refund:'||f.id); UPDATE fleet_aircraft SET returned_at=now(),status='RETURNED' WHERE id=f.id; RETURN f.id; ELSIF p_action='renew' THEN IF p_weeks NOT BETWEEN 1 AND 52 THEN RAISE EXCEPTION 'Lease term must be 1–52 weeks'; END IF; SELECT weekly_rate INTO base FROM aircraft_types WHERE id=f.aircraft_type_id; SELECT renewal_discount INTO discount FROM operating_rules WHERE singleton; rate:=round(base*(1-discount),2); IF bal<rate THEN RAISE EXCEPTION 'Insufficient Smooth Coins'; END IF; INSERT INTO lease_contracts(aircraft_id,company_id,starts_at,ends_at,term_weeks,base_weekly_rate,weekly_rate,renewal) VALUES(f.id,c.id,now(),now()+make_interval(days=>7*p_weeks),p_weeks,base,rate,true) RETURNING id INTO kid; INSERT INTO company_ledger(company_id,entry_type,debit_account,credit_account,amount,company_delta,balance_after,description,reference,idempotency_key) VALUES(c.id,'LEASE_PAYMENT','LESSOR_REVENUE','COMPANY_CASH',rate,-rate,bal-rate,'Renewal first weekly payment – '||f.registration,f.registration,'contract:'||kid||':week:1'); UPDATE fleet_aircraft SET weekly_rate=rate,next_payment_due=now()+interval '7 days',status='AVAILABLE' WHERE id=f.id; RETURN kid; ELSE RAISE EXCEPTION 'Unknown lease action'; END IF; END $$;
CREATE FUNCTION public.validate_dispatch_lease() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT EXISTS(SELECT 1 FROM lease_contracts k JOIN fleet_aircraft f ON f.id=k.aircraft_id WHERE k.aircraft_id=NEW.aircraft_id AND f.returned_at IS NULL AND now()>=k.starts_at AND now()<k.ends_at) THEN RAISE EXCEPTION 'Lease expired — renew before dispatch'; END IF; RETURN NEW; END $$;
CREATE TRIGGER validate_lease_before_dispatch BEFORE INSERT ON public.flights FOR EACH ROW EXECUTE FUNCTION public.validate_dispatch_lease();
DO $$ DECLARE definition text; BEGIN SELECT pg_get_functiondef('public.flight_quote(uuid,text)'::regprocedure) INTO definition; definition:=replace(definition,'IF f.status<>''AVAILABLE'' THEN','IF NOT EXISTS(SELECT 1 FROM public.lease_contracts k WHERE k.aircraft_id=f.id AND now()>=k.starts_at AND now()<k.ends_at) OR f.returned_at IS NOT NULL THEN RAISE EXCEPTION ''Lease expired — renew before dispatch''; END IF; IF f.status<>''AVAILABLE'' THEN'); EXECUTE definition; END $$;
CREATE FUNCTION public.aircraft_finance(p_aircraft uuid) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE f fleet_aircraft%ROWTYPE; k lease_contracts%ROWTYPE; result jsonb; accrued numeric; BEGIN SELECT * INTO f FROM fleet_aircraft WHERE id=p_aircraft AND company_id IN(SELECT id FROM companies WHERE user_id=auth.uid()); IF NOT FOUND THEN RAISE EXCEPTION 'Aircraft not found'; END IF; SELECT * INTO k FROM lease_contracts WHERE aircraft_id=f.id ORDER BY starts_at DESC LIMIT 1; SELECT coalesce(sum(weekly_rate/7*greatest(0,extract(epoch FROM least(now(),ends_at)-starts_at)/86400)),0) INTO accrued FROM lease_contracts WHERE aircraft_id=f.id; SELECT jsonb_build_object('revenue',coalesce(sum(amount) FILTER(WHERE entry_type='TICKET_REVENUE'),0),'fuel',coalesce(sum(amount) FILTER(WHERE entry_type='FUEL_EXPENSE'),0),'airport',coalesce(sum(amount) FILTER(WHERE entry_type='AIRPORT_FEES'),0),'handling',coalesce(sum(amount) FILTER(WHERE entry_type='HANDLING_FEES'),0),'maintenance',coalesce(sum(amount) FILTER(WHERE entry_type='MAINTENANCE_RESERVE'),0),'lease_paid',coalesce(sum(amount) FILTER(WHERE entry_type='LEASE_PAYMENT'),0),'deposit',f.lease_deposit,'lease_accrued',round(accrued,2),'daily_lease',round(k.weekly_rate/7,2),'ends_at',k.ends_at,'term_weeks',k.term_weeks,'weekly_rate',k.weekly_rate,'returned_at',f.returned_at,'flights',(SELECT count(*) FROM flights WHERE aircraft_id=f.id AND status='COMPLETED')) INTO result FROM company_ledger l WHERE l.company_id=f.company_id AND (l.reference=f.registration OR l.reference IN(SELECT id::text FROM flights WHERE aircraft_id=f.id)); RETURN result; END $$;
REVOKE ALL ON FUNCTION public.sync_lease_payments(),public.sign_lease(text,integer),public.manage_lease(uuid,text,integer),public.aircraft_finance(uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.sync_lease_payments(),public.sign_lease(text,integer),public.manage_lease(uuid,text,integer),public.aircraft_finance(uuid) TO authenticated;
REVOKE ALL ON FUNCTION public.validate_dispatch_lease() FROM PUBLIC,anon,authenticated;